                    if (globalScope[GLOBAL_PI_BACKFILL_KEY] === task) {
                        delete globalScope[GLOBAL_PI_BACKFILL_KEY];
                    }
                });
            }
            if (!globalScope[GLOBAL_PLUGIN_WARMUP_KEY] && isConfigured()) {
                (async () => {
                    try {
                        await memoryClient.warmup();
                        globalScope[GLOBAL_PLUGIN_WARMUP_KEY] = true;
                        finishStatus(ctx, status, "connected");
                    }
                    catch (error) {
                        log("Pi plugin memory warmup failed", { error: String(error) }, "error");
                        finishStatus(ctx, status, "error");
                    }
                })();
            }
            else {
                finishStatus(ctx, status, "connected");
            }
            if (event.reason === "resume") {
                sessionContext.markSeen(sessionId);
                await sessionContext.loadRestore(ctx);
            }
        }
        catch (error) {
            log("Pi session_start error", { error: String(error) }, "error");
            finishStatus(ctx, status, "error");
        }
    });
    pi.on("before_agent_start", async (event, ctx) => {
        // Refresh first so the enabled check reads the current file, then capture
        // this retrieval's allowance before the async search starts: a later
        // config edit must not change an operation already in progress.
        refreshConfigIfChanged(ctx.cwd);
        // The default guards partial CONFIG stubs in tests.
        const budgetBytes = tokensToByteCeiling(CONFIG.retrievalMaxTokens ?? DEFAULT_RETRIEVAL_MAX_TOKENS);
        if (!isConfigured() || (!CONFIG.chatMessage.enabled && !CONFIG.compaction?.enabled))
            return;
        const status = startStatus(ctx, "recalling");
        try {
            const extra = await sessionContext.recall(ctx, event.prompt, budgetBytes);
            finishStatus(ctx, status, "connected");
            return extra ? { systemPrompt: event.systemPrompt + extra } : undefined;
        }
        catch (error) {
            log("Pi before_agent_start retrieval error", { error: String(error) }, "error");
            finishStatus(ctx, status, "error");
            return undefined;
        }
    });
    // OMMS adds memories after compaction; it never replaces Pi's own summary (no
    // session_before_compact handler).
    pi.on("session_compact", async (_event, ctx) => {
        sessionContext.markSeen(ctx.sessionManager.getSessionId());
        await sessionContext.loadRestore(ctx);
    });
    pi.on("agent_settled", async (_event, ctx) => {
        if (!isConfigured())
            return;
        const status = startStatus(ctx, "capturing");
        try {
            const entries = toSessionEntries(ctx.sessionManager.getBranch());
            const liveModels = createPiLiveModels(ctx, piNotifier(ctx));
            const provider = liveModels.capture;
            const captureResult = await capturePiSettledWorkUnit({
                sessionId: ctx.sessionManager.getSessionId(),
                directory: ctx.cwd,
                entries,
                provider,
                state: captureState,
                prompt: {
                    providerId: ctx.model?.provider ?? null,
                    modelId: ctx.model?.id ?? null,
                },
                notify: piNotifier(ctx),
            });
            // Housekeeping always; deletion by age only when the user turned it on (ADR-051).
            // Not awaited: a slow or failed run never holds up or breaks the session.
            void import("../../services/cleanup-service.js")
                .then(({ cleanupService }) => cleanupService.runDailyMaintenance(CONFIG.autoDeleteOldMemories === true, CONFIG))
                .catch((error) => log("Pi daily maintenance failed", { code: errorCode(error) }, "error"));
            // Pi records each settled prompt in the shared store; the shared pass learns from it.
            const settled = lastSettledPiPrompt(entries);
            if (settled) {
                await recordPiPrompt(ctx.sessionManager.getSessionId(), settled.entryId, ctx.cwd, settled.text).catch((error) => log("Pi prompt record failed", { code: errorCode(error) }, "error"));
                if (!isTrivialPrompt(settled.text) &&
                    CONFIG.userProfileAnalysisInterval > 0 &&
                    !memoryClient.getEmbeddingInitError?.()) {
                    await learnPiProfile({
                        directory: ctx.cwd,
                        model: liveModels.profile,
                        notify: piNotifier(ctx),
                    });
                }
            }
            finishStatus(ctx, status, captureResult.status === "failed" ? "error" : "connected");
        }
        catch (error) {
            log("Pi agent_settled error", { error: String(error) }, "error");
            finishStatus(ctx, status, "error");
        }
    });
    pi.on("session_shutdown", async (_event, ctx) => {
        selfUpdate.stop();
        clearStatus(ctx);
        recallRows.reset(ctx);
        sessionContext.reset();
        latestCtx = null;
        captureState = createPiCaptureState();
        globalThis[GLOBAL_PLUGIN_WARMUP_KEY] = false;
        const task = globalThis[GLOBAL_PI_BACKFILL_KEY];
        task?.controller.abort();
        if (task)
            await task.promise;
        backfillSessionId = null;
        try {
            await memoryClient.close();
        }
        catch {
            // Idempotent cleanup: closing an already-closed client must never fail
            // the shutdown flow across quit, reload, new, resume, and fork.
        }
    });
    pi.registerTool({
        name: "memory",
        label: "Memory",
        description: memoryToolDescription(getLanguageName(CONFIG.autoCaptureLanguage || "en")),
        parameters: Type.Object({
            mode: Type.Optional(Type.Union(MEMORY_TOOL_MODES.map((mode) => Type.Literal(mode)))),
            content: Type.Optional(Type.String()),
            query: Type.Optional(Type.String()),
            tags: Type.Optional(Type.String()),
            type: Type.Optional(Type.String()),
            topic: Type.Optional(Type.String()),
            done: Type.Optional(Type.String()),
            doing: Type.Optional(Type.String()),
            next: Type.Optional(Type.String()),
            memoryId: Type.Optional(Type.String()),
            limit: Type.Optional(Type.Number()),
            scope: Type.Optional(Type.Union([Type.Literal("project"), Type.Literal("all-projects")])),
            fromPath: Type.Optional(Type.String()),
            fromHash: Type.Optional(Type.String()),
            outputPath: Type.Optional(Type.String()),
            inputPath: Type.Optional(Type.String()),
            dryRun: Type.Optional(Type.Boolean()),
            allowLinkedSource: Type.Optional(Type.Boolean()),
            spaceAction: Type.Optional(Type.String()),
            spaceName: Type.Optional(Type.String()),
            spaceTo: Type.Optional(Type.String()),
            spaceSince: Type.Optional(Type.String()),
            spaceUntil: Type.Optional(Type.String()),
            spaceProject: Type.Optional(Type.String()),
            spaceIn: Type.Optional(Type.String()),
        }),
        async execute(_toolCallId, args, _signal, _onUpdate, ctx) {
            const result = await executeMemoryOperation(args, {
                config: configModule,
                directory: ctx.cwd,
                host: "pi",
                hostSessionId: ctx.sessionManager.getSessionId(),
            });
            return {
                content: [{ type: "text", text: JSON.stringify(result) }],
                details: {},
            };
        },
    });
    pi.registerCommand("omms-recall", {
        description: "Unfold or fold the OMMS recall rows",
        handler: async (_args, ctx) => {
            refreshConfigIfChanged(ctx.cwd);
            await recallRows.toggleAll(ctx, CONFIG.visibleRecall !== false);
        },
    });
    registerPiSkillsTool(pi, configModule);
    registerPiHistoryImportCommand(pi, () => latestCtx);
}
